// Alias canónicos para resolución de claves
SACRED_BOOKS_I18N['epistle_1_corinthians'] = SACRED_BOOKS_I18N['epistle_1corinthians'];
SACRED_BOOKS_I18N['epistle_1_john'] = SACRED_BOOKS_I18N['epistle_1john'];
SACRED_BOOKS_I18N['epistle_1corinthians'] = SACRED_BOOKS_I18N['epistle_1_corinthians'];
SACRED_BOOKS_I18N['epistle_1john'] = SACRED_BOOKS_I18N['epistle_1_john'];

export function getLocalizedBookTitle(bookKey, lang = 'es') {
  if (!bookKey) return '';
  if (SACRED_BOOKS_I18N[bookKey] && SACRED_BOOKS_I18N[bookKey].title) {
    return SACRED_BOOKS_I18N[bookKey].title[lang] || SACRED_BOOKS_I18N[bookKey].title.es || '';
  }
  const found = SACRED_BOOKS_INDEX.find(b => b.key === bookKey);
  return found ? found.title : bookKey;
}

export function getLocalizedBookSubtitle(bookKey, lang = 'es') {
  if (!bookKey) return '';
  if (SACRED_BOOKS_I18N[bookKey] && SACRED_BOOKS_I18N[bookKey].subtitle) {
    return SACRED_BOOKS_I18N[bookKey].subtitle[lang] || SACRED_BOOKS_I18N[bookKey].subtitle.es || '';
  }
  const found = SACRED_BOOKS_INDEX.find(b => b.key === bookKey);
  return found ? found.subtitle : '';
}

export function getScriptureBookTitle(item, lang = 'es') {
  if (!item) return '';
  const bKey = item.libroKey;
  if (bKey && SACRED_BOOKS_I18N[bKey] && SACRED_BOOKS_I18N[bKey].title) {
    return SACRED_BOOKS_I18N[bKey].title[lang] || SACRED_BOOKS_I18N[bKey].title.es || item.libro;
  }
  return item.libro || '';
}

export function getScriptureSection(item, lang = 'es') {
  if (!item) return '';
  const bKey = item.libroKey;
  if (bKey && SACRED_BOOKS_I18N[bKey] && SACRED_BOOKS_I18N[bKey].section) {
    return SACRED_BOOKS_I18N[bKey].section[lang] || SACRED_BOOKS_I18N[bKey].section.es || item.seccion || '';
  }
  return item.seccion || '';
}

export function getScriptureOrigLang(item, lang = 'es') {
  if (!item) return '';
  const bKey = item.libroKey;
  if (bKey && SACRED_BOOKS_I18N[bKey] && SACRED_BOOKS_I18N[bKey].langLabel) {
    return SACRED_BOOKS_I18N[bKey].langLabel[lang] || SACRED_BOOKS_I18N[bKey].langLabel.es || item.idiomaLiturgicoOriginal || '';
  }
  return item.idiomaLiturgicoOriginal || '';
}

export function formatChapterLabel(item, lang = 'es') {
  if (!item) return '';
  const num = item.capituloNumero || (item.id && item.id.match(/chapter_(\d+)/) ? item.id.match(/chapter_(\d+)/)[1] : '');
  
  if (lang === 'zh' || lang === 'ja') {
    return num ? `第 ${num} 章` : item.capitulo;
  }
  if (lang === 'en') {
    return num ? `Chapter ${num}` : item.capitulo;
  }
  if (lang === 'fr') {
    return num ? `Chapitre ${num}` : item.capitulo;
  }
  if (lang === 'pt') {
    return num ? `Capítulo ${num}` : item.capitulo;
  }
  if (lang === 'it') {
    return num ? `Capitolo ${num}` : item.capitulo;
  }
  if (lang === 'de') {
    return num ? `Kapitel ${num}` : item.capitulo;
  }
  if (lang === 'ru') {
    return num ? `Глава ${num}` : item.capitulo;
  }
  if (lang === 'ar') {
    return num ? `الفصل ${num}` : item.capitulo;
  }
  if (lang === 'he') {
    return num ? `פרק ${num}` : item.capitulo;
  }
  if (lang === 'hi') {
    return num ? `अध्याय ${num}` : item.capitulo;
  }
  if (lang === 'la') {
    return num ? `Caput ${num}` : item.capitulo;
  }
  if (lang === 'bn') {
    return num ? `অধ্যায় ${num}` : item.capitulo;
  }
  if (lang === 'id') {
    return num ? `Bab ${num}` : item.capitulo;
  }
  if (lang === 'ur') {
    return num ? `باب ${num}` : item.capitulo;
  }
  if (lang === 'sw') {
    return num ? `Sura ${num}` : item.capitulo;
  }
  if (lang === 'es') {
    return num ? `Capítulo ${num}` : item.capitulo;
  }
  return item.capitulo || '';
}

export function getScriptureById(id) {
  if (!id) return null;
  return SCRIPTURES_CATALOG.find(item => item.id === id) || null;
}

export function getScripturesByBook(bookKey) {
  if (!bookKey) return [];
  return SCRIPTURES_CATALOG.filter(item => item.libroKey === bookKey);
}

export function getAdjacentScriptures(id) {
  if (!id) return { prev: null, next: null, currentIndex: 0, totalInBook: 1, isCrossBookNext: false, isCrossBookPrev: false };
  const idx = SCRIPTURES_CATALOG.findIndex(item => item.id === id);
  if (idx === -1) return { prev: null, next: null, currentIndex: 0, totalInBook: 1, isCrossBookNext: false, isCrossBookPrev: false };
  const currentItem = SCRIPTURES_CATALOG[idx];

  const bookItems = SCRIPTURES_CATALOG.filter(item => item.libroKey === currentItem.libroKey);
  const currentInBookIndex = bookItems.findIndex(item => item.id === id);
  const totalInBook = bookItems.length;

  let prev = null;
  let next = null;
  let isCrossBookPrev = false;
  let isCrossBookNext = false;

  for (let i = idx - 1; i >= 0; i--) {
    if (SCRIPTURES_CATALOG[i].libroKey === currentItem.libroKey) {
      prev = SCRIPTURES_CATALOG[i];
      break;
    }
  }

  for (let i = idx + 1; i < SCRIPTURES_CATALOG.length; i++) {
    if (SCRIPTURES_CATALOG[i].libroKey === currentItem.libroKey) {
      next = SCRIPTURES_CATALOG[i];
      break;
    }
  }

  // Si no hay siguiente dentro del mismo libro, permitir continuar al primer capítulo del siguiente libro canónico
  if (!next && idx + 1 < SCRIPTURES_CATALOG.length) {
    next = SCRIPTURES_CATALOG[idx + 1];
    isCrossBookNext = true;
  }

  // Si no hay anterior dentro del mismo libro, permitir retroceder al último capítulo del libro canónico anterior
  if (!prev && idx - 1 >= 0) {
    prev = SCRIPTURES_CATALOG[idx - 1];
    isCrossBookPrev = true;
  }

  return {
    prev,
    next,
    currentIndex: currentInBookIndex >= 0 ? currentInBookIndex : 0,
    totalInBook: totalInBook > 0 ? totalInBook : 1,
    isCrossBookNext,
    isCrossBookPrev
  };
}



